using System;using System.IO;using System.Diagnostics;using System.Windows.Forms;
namespace SargasPC {
 public sealed partial class Window {
  private void LaunchPcScan(){try{string target=WindowsServiceAccess.InstalledTool("SARGON.Setup.exe",49);Process.Start(new ProcessStartInfo(target,"--scan-settings"){UseShellExecute=true,Verb="runas"});status.Text="Atvertas diskų patikros ir eigos langas. Jame pasirinkite diskus ir pradėkite / tęskite patikrą.";}catch(Exception e) when(e is IOException||e is UnauthorizedAccessException||e is System.ComponentModel.Win32Exception){MessageBox.Show(this,"Diskų patikros langas neatvertas. Įdiekite ir 0.49 paslaugos dalį. "+Data.Clean(e.Message));}}
  private void LaunchDatabaseUpdate(){try{string target=WindowsServiceAccess.InstalledTool("SARGON.Setup.exe",49);Process.Start(new ProcessStartInfo(target,"--update-databases"){UseShellExecute=true,Verb="runas"});status.Text="Atvertas administratoriaus bazių atnaujinimo langas. Jame pasirinkite ir užsakykite atnaujinimą.";}catch(Exception e) when(e is IOException||e is UnauthorizedAccessException||e is System.ComponentModel.Win32Exception){MessageBox.Show(this,"Bazių atnaujinimo langas neatvertas. "+Data.Clean(e.Message)+" Pirmiausia įdiekite 0.49 ar naujesnio bendro diegiklio paslaugos dalį.");}}
  private void LaunchCaseReview(){try{string target=WindowsServiceAccess.InstalledTool("SARGON.CaseReview.exe");Process.Start(new ProcessStartInfo(target,"--gui"){UseShellExecute=true,Verb="runas"});}catch(Exception e) when(e is IOException||e is UnauthorizedAccessException||e is System.ComponentModel.Win32Exception){MessageBox.Show(this,"Radinių langas neatvertas. Įrankis turi būti įdiegtas vientisu diegikliu; administratoriaus UAC patvirtinimas būtinas.");}}
  private void UnifiedReadinessDialog(){using(var d=new Form{Text="Bendra SARGON parengtis",Width=840,Height=650,StartPosition=FormStartPosition.CenterParent}){var text=new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical};var panel=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=115,AutoScroll=true};var refresh=new Button{Text="Patikrinti iš naujo",Width=220,Height=45};var cases=new Button{Text="Atverti radinių valdymą",Width=290,Height=45};Action load=()=>{ServiceHeartbeat s=null;try{string path=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData),"SARGONService","Public","status.json");FolderMonitor.NoLinks(path);s=ServiceHeartbeat.Read(path);}catch(Exception e) when(e is IOException||e is UnauthorizedAccessException||e is ArgumentException||e is InvalidOperationException){}text.Text=ReadinessSummary.Assess(s,WindowsServiceAccess.Running(),DateTime.UtcNow.Ticks)+(core.SharedReadOnlyEngine?"\r\n\r\nBendro vietinio variklio failų būsena (šios paskyros kontrolės data yra tik istorija):\r\n":"\r\n\r\nVartotojo atskiro vietinio variklio būsena:\r\n")+core.LocalEngineStatus();};refresh.Click+=(s,e)=>load();cases.Click+=(s,e)=>LaunchCaseReview();var update=new Button{Text="Atnaujinti bendras bazes…",Width=290,Height=45};update.Click+=(s,e)=>LaunchDatabaseUpdate();var pc=new Button{Text="Diskai, grafikas ir eiga…",Width=290,Height=45};pc.Click+=(s,e)=>LaunchPcScan();panel.Controls.AddRange(new Control[]{refresh,cases,update,pc});d.Controls.Add(text);d.Controls.Add(panel);ThemeDialog(d);load();d.ShowDialog(this);}}
 }
}
